 Object.assign(crm,{rework,closeModal,openOpportunityForm,saveOpportunity,refreshOpportunityStagesV2,togglePartyPicker,searchParties,selectParty,openQuickParty,closeQuickParty,toggleQuickPartyKind,searchQuickPartyCompany,selectQuickPartyCompany,saveQuickParty,showContextMenu,contextOpen,contextEdit,contextActivity,contextDocument,contextClose,reopenContextMenu,openContextStage,applyContextStage,openContextOwner,openContextPriority,applyContextField,contextArchive,openLinkDocument,linkDocument,openQuickActivity,saveQuickActivity,openCompleteActivity,completeActivity,postponeActivity,cancelActivity,loadActivitiesV2,setActivityViewV2,setActivityFilterV2,dragActivity,dropActivityDate,loadReportsV2,setReportFilterV2,exportReports,printReports});
